func (r *queryResolver) GetAllFavoriteVendors(ctx context.Context) (*model.FavoriteVendorMateData, error) {
	// Fetch the user ID
	userIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get user ID: %v", err)
	}

	// Fetch favorite vendors for the user
	var favoriteVendors []*model.FavoriteVendor
	if err := r.DB.
		Joins("JOIN vendors ON vendors.id = favorite_vendors.vendor_id").
		Where("favorite_vendors.user_id = ?", userIDStr).
		Preload("User").
		Preload("Vendor").
		Find(&favoriteVendors).Error; err != nil {
		return nil, fmt.Errorf("failed to fetch favorite vendors: %v", err)
	}

	// Count of favorite vendors
	count := len(favoriteVendors)

	// Find the most favorited vendor
	var mostFavoritedVendor model.Vendor
	if err := r.DB.
		Table("vendors").
		Select("vendors.*, COUNT(favorite_vendors.vendor_id) as favorited_count").
		Joins("JOIN favorite_vendors ON favorite_vendors.vendor_id = vendors.id").
		Group("vendors.id").
		Order("favorited_count DESC").
		Limit(1).
		First(&mostFavoritedVendor).Error; err != nil {
		if err != gorm.ErrRecordNotFound {
			return nil, fmt.Errorf("failed to fetch most favorited vendor: %v", err)
		}
		// Handle case where no vendors are found
		mostFavoritedVendor = model.Vendor{}
	}

	// Return the FavoriteVendorMateData
	return &model.FavoriteVendorMateData{
		FavoriteVendors:     favoriteVendors,
		Count:               count,
		MostFavoritedVendor: &mostFavoritedVendor,
	}, nil
}

func (r *queryResolver) GetProductforVpm(ctx context.Context) (*model.ProductforVpm, error) {
	// Step 1: Extract vendor ID from context
	vendorIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}
	vendorID, err := uuid.Parse(*vendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid vendor ID: %v", err)
	}

	// Step 2: Fetch all products associated with the vendor
	var products []model.Product
	err = r.DB.Where("vendor_id = ?", vendorID).Find(&products).Error
	if err != nil {
		return nil, fmt.Errorf("failed to retrieve products: %v", err)
	}

	// Step 3: Count the total number of SideSwappers related to this vendor via products
	var sideSwapperCount int64
	err = r.DB.Model(&model.SideSwapper{}).
		Joins("JOIN side_swapper_products ON side_swappers.id = side_swapper_products.side_swapper_id").
		Joins("JOIN products ON side_swapper_products.product_id = products.id").
		Where("products.vendor_id = ?", vendorID).
		Count(&sideSwapperCount).Error
	if err != nil {
		return nil, fmt.Errorf("failed to count SideSwappers: %v", err)
	}

	// Step 4: Fetch related carts using product IDs
	var carts []model.Cart
	productIDs := make([]uuid.UUID, len(products))
	for i, product := range products {
		productIDs[i] = product.ID
	}

	err = r.DB.Joins("JOIN cart_items ON carts.id = cart_items.cart_id").
		Where("cart_items.product_id IN ?", productIDs).
		Preload("Items.Product").
		Find(&carts).Error
	if err != nil {
		return nil, fmt.Errorf("failed to retrieve carts: %v", err)
	}

	// Step 5: Calculate total revenue, profit, etc.
	totalRevenue := 0.0
	totalProfit := 0.0
	//totalProducts := 0
	lowStockCount := "0"
	totalProducts := len(products)

	for _, cart := range carts {
		for _, item := range cart.Items {
			if item.Product != nil && item.Product.Price != nil {
				// Convert string price to float64
				price, err := strconv.ParseFloat(*item.Product.Price, 64)
				if err != nil {
					return nil, fmt.Errorf("invalid product price for product ID %s: %v", item.Product.ID, err)
				}

				// Assuming product cost is available in item.Product.Cost
				cost := 0.0 // Default cost, adjust as per actual Product model
				if item.Product.Cost != nil {
					cost, err = strconv.ParseFloat(*item.Product.Cost, 64)
					if err != nil {
						return nil, fmt.Errorf("invalid product cost for product ID %s: %v", item.Product.ID, err)
					}
				}

				// Calculate revenue and profit
				totalRevenue += price * float64(item.Quantity)
				totalProfit += (price - cost) * float64(item.Quantity)
				//totalProducts += item.Quantity
				//totalProducts = len(products)

				// Assuming Product has a LowStockThreshold field
				/*if item.Quantity <= item.Product.LowStockThreshold {
					lowStockCount++
				}*/
			}
		}
	}

	// Step 6: Prepare the ProductforVpm response
	productForVpm := &model.ProductforVpm{
		SideSwappers:          fmt.Sprintf("%d", sideSwapperCount), // Total SideSwappers
		PersonalDeliveryItems: fmt.Sprintf("%d", len(carts)),       // Total carts (personal orders)
		ZukoDeliveryItems:     "N/A",                               // Add logic for ZukoDeliveryItems if needed
		TotalRevenue:          fmt.Sprintf("%.2f", totalRevenue),
		TotalProfit:           fmt.Sprintf("%.2f", totalProfit),
		TotalProducts:         fmt.Sprintf("%d", totalProducts),
		LowStock:              &lowStockCount,
	}

	return productForVpm, nil
}

func (r *queryResolver) GetCartUsersByVendorID(ctx context.Context) ([]*model.Order, error) {
	// Retrieve and parse vendor ID
	vendorIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}
	vendorUUID, err := uuid.Parse(*vendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid vendor ID: %v", err)
	}

	// Retrieve orders for the specified vendor ID with product details
	var orders []*model.Order
	err = r.DB.Preload("OrderItems", "vendor_id = ?", vendorUUID).
		Preload("OrderItems.CartItem.Product").
		Joins("JOIN groups ON orders.id = groups.order_items_id").
		Where("groups.vendor_id = ?", vendorUUID).
		Find(&orders).Error
	if err != nil {
		return nil, fmt.Errorf("failed to retrieve orders: %v", err)
	}

	// Deduplicate orders based on their IDs
	uniqueOrdersMap := make(map[string]*model.Order)
	for _, order := range orders {
		uniqueOrdersMap[order.ID.String()] = order
	}

	// Convert map back to a slice
	uniqueOrders := make([]*model.Order, 0, len(uniqueOrdersMap))
	for _, order := range uniqueOrdersMap {
		uniqueOrders = append(uniqueOrders, order)
	}

	return uniqueOrders, nil
}

func (r *queryResolver) GetCalculateOrderGrowthData(ctx context.Context) (*model.GrowthData, error) {
	// Retrieve and parse vendor ID
	vendorIDStr, err := r.Query().GetID(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to get vendor ID: %v", err)
	}
	vendorUUID, err := uuid.Parse(*vendorIDStr)
	if err != nil {
		return nil, fmt.Errorf("invalid vendor ID: %v", err)
	}

	// Define the start of the week (Monday)
	startOfWeek := time.Now().Truncate(24 * time.Hour).Add(-time.Duration(time.Now().Weekday()-1) * 24 * time.Hour)
	endOfWeek := startOfWeek.Add(7 * 24 * time.Hour)

	// Query for current week orders count
	var currentWeekOrdersCount int64
	err = r.DB.Model(&model.Order{}).
		Joins("JOIN groups ON orders.id = groups.order_items_id").
		Where("groups.vendor_id = ? AND orders.created_at >= ? AND orders.created_at < ?", vendorUUID, startOfWeek, endOfWeek).
		Count(&currentWeekOrdersCount).Error
	if err != nil {
		return nil, fmt.Errorf("failed to retrieve current week orders count: %v", err)
	}

	// Define the previous week date range
	startOfLastWeek := startOfWeek.Add(-7 * 24 * time.Hour)
	endOfLastWeek := startOfLastWeek.Add(7 * 24 * time.Hour)

	// Query for last week orders count
	var lastWeekOrdersCount int64
	err = r.DB.Model(&model.Order{}).
		Joins("JOIN groups ON orders.id = groups.order_items_id").
		Where("groups.vendor_id = ? AND orders.created_at >= ? AND orders.created_at < ?", vendorUUID, startOfLastWeek, endOfLastWeek).
		Count(&lastWeekOrdersCount).Error
	if err != nil {
		return nil, fmt.Errorf("failed to retrieve last week orders count: %v", err)
	}

	// Query for total orders count (all time)
	var totalOrdersCount int64
	err = r.DB.Model(&model.Order{}).
		Joins("JOIN groups ON orders.id = groups.order_items_id").
		Where("groups.vendor_id = ?", vendorUUID).
		Count(&totalOrdersCount).Error
	if err != nil {
		return nil, fmt.Errorf("failed to retrieve total orders count: %v", err)
	}

	// Calculate growth percentage
	var growthPercentage float64
	if lastWeekOrdersCount > 0 {
		growthPercentage = float64(currentWeekOrdersCount-lastWeekOrdersCount) / float64(lastWeekOrdersCount) * 100
	} else {
		growthPercentage = 100 // If there were no orders last week, assume 100% growth
	}

	// Create GrowthData struct with current week order count, total orders, and growth percentage
	growthData := &model.GrowthData{
		TotalOrders: fmt.Sprintf("%d", totalOrdersCount),                     // Total orders for the vendor
		Orders:      fmt.Sprintf("%d", currentWeekOrdersCount),               // Current week orders
		Percentage:  fmt.Sprintf("+%.0f%% from last week", growthPercentage), // Growth percentage
	}

	return growthData, nil
}

// GrowthData struct to represent growth statistics
type GrowthData struct {
	TotalOrders string `json:"totalOrders"` // Total orders over the vendor's lifetime
	Orders      string `json:"orders"`      // Current week orders
	Percentage  string `json:"percentage"`  // Growth percentage
}

